//! # Generated Protobuf Types and Services
//!
//! This module encapsulates the Rust code generated by `tonic-build` from the 
//! `mpc.proto` definition file. It provides the strongly-typed message structs 
//! and gRPC service traits used throughout the MPC network layer.

// Include the generated code from the build script.
// The module name corresponds to the package defined in the .proto file.
pub mod mpc {
    tonic::include_proto!("mpc");
}

// Re-export all generated types to the parent module for cleaner imports.
pub use mpc::*;


